def count_mono_triangles(n, r, b):
    """Calculates the number of monochromatic triangles for n vertices with r red and b blue."""
    if r < 3:
        c_r3 = 0
    else:
        c_r3 = r * (r - 1) * (r - 2) // 6

    if b < 3:
        c_b3 = 0
    else:
        c_b3 = b * (b - 1) * (b - 2) // 6

    return c_r3 + c_b3

def check_n(n):
    """Checks if n guarantees at least 2 monochromatic triangles."""
    if n < 3:
        return False

    # We must check all possible splits (r, b) where r + b = n.
    # We iterate r from floor(n/2) up to n, as the split (r, n-r) covers all cases.
    for r in range(n // 2, n + 1):
        b = n - r
        num_mono = count_mono_triangles(n, r, b)
        if num_mono < 2:
            return False
    return True

print("Testing n=3:", check_n(3))
print("Testing n=4:", check_n(4))
print("Testing n=5:", check_n(5))
print("Testing n=6:", check_n(6))
print("Testing n=7:", check_n(7))
